// Form & Portal Lookup — Phase 2
// Enriches the report with form download links and portal info
// for the determined visa target (uk or schengen).

const report = $input.first().json;
const visaTarget = report.visa_target || 'schengen';
const schengenCountry = (report.schengen_main_country || '').toLowerCase();

// Curated form and portal data (mirrors visa_forms.json / visa_portals.json)
const FORMS = {
  uk: [
    {
      id: 'uk_online_application',
      title: 'UK Visa Online Application (UKVI)',
      url: 'https://www.gov.uk/apply-uk-visa',
      format: 'Online portal',
      mandatory: true,
      notes: 'Complete before your appointment. Pay fee online.'
    },
    {
      id: 'uk_docs_guide',
      title: 'Supporting Documents Guide',
      url: 'https://www.gov.uk/government/publications/visitor-visa-guide-to-supporting-documents',
      format: 'PDF guidance',
      mandatory: false,
      notes: 'Useful reference for preparing financial evidence.'
    }
  ],
  schengen: [
    {
      id: 'schengen_application_form',
      title: 'Schengen Visa Application Form',
      url: 'https://home-affairs.ec.europa.eu/system/files/2020-04/annex_16_application_form_for_schengen_visa_en_0.pdf',
      format: 'PDF (fillable)',
      mandatory: true,
      notes: 'Print, fill in block capitals, and sign by hand.'
    }
  ]
};

const PORTALS = {
  uk: {
    upload_portal: {
      name: 'UKVCAS',
      url: 'https://www.ukvcas.co.uk/',
      accepted_formats: ['PDF', 'JPEG', 'PNG'],
      max_file_mb: 6,
      upload_timing: 'Before appointment'
    },
    appointment_portals: [{
      name: 'UKVCAS',
      booking_url: 'https://www.ukvcas.co.uk/book-appointment',
      avg_wait_weeks: 3
    }],
    tracking_url: 'https://www.gov.uk/track-visa-application'
  },
  schengen: {
    upload_portal: {
      name: 'VFS Global / TLScontact',
      url: 'https://www.vfsglobal.com/',
      accepted_formats: ['PDF', 'JPEG'],
      max_file_mb: 2,
      upload_timing: 'At appointment'
    },
    country_portals: {
      france: { portal_name: 'TLScontact', booking_url: 'https://register.tlscontact.com/', tracking_url: 'https://fr.tlscontact.com/track', avg_wait_weeks: 3 },
      germany: { portal_name: 'TLScontact', booking_url: 'https://register.tlscontact.com/', tracking_url: 'https://de.tlscontact.com/track', avg_wait_weeks: 4 },
      spain: { portal_name: 'VFS Global', booking_url: 'https://www.vfsglobal.com/spain/', tracking_url: 'https://www.vfsglobal.com/spain/track', avg_wait_weeks: 2 },
      italy: { portal_name: 'VFS Global', booking_url: 'https://www.vfsglobal.com/italy/', tracking_url: 'https://www.vfsglobal.com/italy/track', avg_wait_weeks: 3 },
      netherlands: { portal_name: 'VFS Global', booking_url: 'https://www.vfsglobal.com/netherlands/', tracking_url: 'https://www.vfsglobal.com/netherlands/track', avg_wait_weeks: 3 },
      greece: { portal_name: 'VFS Global', booking_url: 'https://www.vfsglobal.com/greece/', tracking_url: 'https://www.vfsglobal.com/greece/track', avg_wait_weeks: 2 }
    },
    tracking_url: 'https://www.vfsglobal.com/track'
  }
};

const forms = FORMS[visaTarget] || [];
const portalData = PORTALS[visaTarget] || {};

let appointmentPortals = portalData.appointment_portals || [];
let trackingUrl = portalData.tracking_url || '';

if (visaTarget === 'schengen' && schengenCountry) {
  const cp = (portalData.country_portals || {})[schengenCountry];
  if (cp) {
    appointmentPortals = [cp];
    trackingUrl = cp.tracking_url || trackingUrl;
  }
}

return [{
  json: {
    ...report,
    forms,
    upload_portal: portalData.upload_portal || null,
    appointment_portals: appointmentPortals,
    tracking_url: trackingUrl
  }
}];

// Tracker Init — Phase 2
// Creates tracker_items rows in the database for the saved application.
// This node runs after 'Save Report to Database1' and uses the app_id
// returned by that node along with the enriched report.

const input = $input.first().json;
const appId = input.app_id || input.id;
const report = input.report || input;

if (!appId) {
  return [{ json: { ...input, tracker_init: 'skipped — no app_id' } }];
}

// Build tracker items list
const now = new Date().toISOString();
const items = [];
let order = 0;

// Documents
for (const doc of (report.mandatory_documents || [])) {
  items.push({
    application_id: appId,
    item_type: 'document',
    label: doc.document,
    details: doc.details,
    status: 'pending',
    link: report.upload_portal?.url || null,
    link_label: report.upload_portal ? 'Upload portal' : null,
    sort_order: order++,
    updated_at: now
  });
}

// Mandatory forms
for (const form of (report.forms || []).filter(f => f.mandatory)) {
  items.push({
    application_id: appId,
    item_type: 'step',
    label: `Download & complete: ${form.title}`,
    details: form.description,
    status: 'pending',
    link: form.url,
    link_label: `Download ${form.format}`,
    notes: form.notes,
    sort_order: order++,
    updated_at: now
  });
}

// Appointment
if (report.appointment_portals?.length) {
  const portal = report.appointment_portals[0];
  items.push({
    application_id: appId,
    item_type: 'appointment',
    label: `Book appointment — ${portal.portal_name || portal.name}`,
    details: `~${portal.avg_wait_weeks || 3} week wait`,
    status: 'pending',
    link: portal.booking_url,
    link_label: 'Book appointment',
    sort_order: order++,
    updated_at: now
  });
}

// Upload step
if (report.upload_portal) {
  items.push({
    application_id: appId,
    item_type: 'step',
    label: 'Upload documents to portal',
    details: `${report.upload_portal.name} · Max ${report.upload_portal.max_file_mb}MB`,
    status: 'pending',
    link: report.upload_portal.url,
    link_label: 'Open portal',
    sort_order: order++,
    updated_at: now
  });
}

// Tracking
if (report.tracking_url) {
  items.push({
    application_id: appId,
    item_type: 'decision',
    label: 'Track application status',
    details: 'Use your reference number to check status online.',
    status: 'pending',
    link: report.tracking_url,
    link_label: 'Track application',
    sort_order: order++,
    updated_at: now
  });
}

// Decision
items.push({
  application_id: appId,
  item_type: 'decision',
  label: 'Receive visa decision',
  details: `Expected within ${report.processing_time || 'stated processing time'}.`,
  status: 'pending',
  sort_order: order++,
  updated_at: now
});

return [{ json: { ...input, tracker_items_created: items.length, tracker_items: items } }];

// Appointment Booking Formatter — Phase 2
// Takes user-provided appointment details and generates:
// 1. A formatted confirmation message
// 2. An iCal (.ics) string for calendar import

const input = $input.first().json;
const {
  portal_name = 'Visa Application Centre',
  appointment_date = '',
  appointment_time = '09:00',
  location = '',
  reference_number = '',
  visa_type = 'Visa'
} = input;

// Generate ICS content
const pad = n => String(n).padStart(2, '0');
let dtstart = '';
try {
  const [y, m, d] = appointment_date.split('-').map(Number);
  const [h, min] = appointment_time.split(':').map(Number);
  dtstart = `${y}${pad(m)}${pad(d)}T${pad(h)}${pad(min)}00`;
} catch (e) {
  const now = new Date();
  dtstart = now.toISOString().replace(/[-:]/g,'').slice(0,15);
}

const dtend = dtstart.slice(0, -4) + String(Number(dtstart.slice(-6, -4)) + 1).padStart(2, '0') + '00';
const dtstamp = new Date().toISOString().replace(/[-:]/g,'').slice(0,15) + 'Z';
const uid = `visa-${Date.now()}@visa-assistant`;

const description = [
  `Visa Application Appointment`,
  `Visa type: ${visa_type}`,
  `Portal: ${portal_name}`,
  `Reference: ${reference_number}`,
  ``,
  `Bring all original documents and photocopies.`
].join('\\n');

const ics = [
  'BEGIN:VCALENDAR',
  'VERSION:2.0',
  'PRODID:-//Visa Assistant//Phase 2//EN',
  'BEGIN:VEVENT',
  `UID:${uid}`,
  `DTSTAMP:${dtstamp}`,
  `DTSTART:${dtstart}`,
  `DTEND:${dtend}`,
  `SUMMARY:${visa_type} appointment — ${portal_name}`,
  `DESCRIPTION:${description}`,
  `LOCATION:${location}`,
  'STATUS:CONFIRMED',
  'BEGIN:VALARM',
  'TRIGGER:-PT24H',
  'ACTION:DISPLAY',
  'DESCRIPTION:Reminder: Visa appointment tomorrow',
  'END:VALARM',
  'END:VEVENT',
  'END:VCALENDAR'
].join('\r\n') + '\r\n';

const confirmation = [
  `✅ **Appointment recorded!**`,
  ``,
  `📅 **Date:** ${appointment_date} at ${appointment_time}`,
  `📍 **Location:** ${location}`,
  `🏛️ **Portal:** ${portal_name}`,
  `🔖 **Reference:** ${reference_number}`,
  ``,
  `Your iCal file has been generated. Import it into your calendar app to set reminders.`,
  ``,
  `**Don't forget to bring:**`,
  `• All original documents + photocopies`,
  `• Your passport`,
  `• This reference number: ${reference_number}`
].join('\n');

return [{ json: { ...input, ics_content: ics, confirmation_message: confirmation } }];
